import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] products = new long[n];
        for (int i = 0; i < n; i++) products[i] = nextLong();
        // Indices of the strict suffix maxima of the active window, values strictly decreasing.
        int[] queue = new int[n];
        int head = 0, tail = 0;
        long total = 0;
        for (int right = 0; right < n; right++) {
            int left = right - k + 1;
            while (head < tail && queue[head] < left) head++;
            while (tail > head && products[queue[tail - 1]] <= products[right]) tail--;
            queue[tail++] = right;
            if (right >= k - 1) total += tail - head;
        }
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n, k := readInt(), readInt()
	products := make([]int, n)
	for i := range products {
		products[i] = readInt()
	}
	// Indices of the strict suffix maxima of the active window, values strictly decreasing.
	queue := make([]int, n)
	head, tail, total := 0, 0, 0
	for right := 0; right < n; right++ {
		left := right - k + 1
		for head < tail && queue[head] < left {
			head++
		}
		for tail > head && products[queue[tail-1]] <= products[right] {
			tail--
		}
		queue[tail] = right
		tail++
		if right >= k-1 {
			total += tail - head
		}
	}
	fmt.Println(total)
}
